    for (const [dx, dy, r] of [[-0.26, 0.02, 0.24], [0.26, 0.02, 0.24], [0, -0.12, 0.3], [-0.12, -0.02, 0.26], [0.13, -0.04, 0.26]]) bump(dx, dy + 0.03, r, c2);
