    ctx.strokeStyle = '#b07a30'; ctx.lineWidth = 0.5 * u; ctx.beginPath(); ctx.moveTo(px - 1.6 * u, py + 1 * u); ctx.lineTo(px + 0.8 * u, py + 5 * u); ctx.moveTo(px + 1.6 * u, py + 1 * u); ctx.lineTo(px - 0.8 * u, py + 5 * u); ctx.stroke();
