      ctx.fillStyle = '#2f6a3a'; for (const d of [-1, 1]) for (let s = 1; s < 5; s++) ctx.fillRect(wx + d * (ww / 2 + 0.8 * u) - (d < 0 ? 3.4 * u : 0), wy + s * 2 * u, 3.4 * u, 0.4 * u);
