  ctx.fillStyle = '#3f6a3a'; ctx.beginPath(); ctx.moveTo(W * 0.72, H * 0.62); ctx.lineTo(W * 0.98, H * 0.62); ctx.lineTo(W, H * 0.7); ctx.lineTo(W * 0.7, H * 0.7); ctx.fill();
