  ctx.fillStyle = '#3a2e2a'; ctx.fillRect(W * 0.75, H * 0.72, W * 0.2, H * 0.18); ctx.fillStyle = '#f2d890'; ctx.fillRect(W * 0.76, H * 0.73, W * 0.18, H * 0.1);
