      const band = (v0, v1, col) => { const pts = []; for (let i = 0; i <= 30; i++) pts.push(at(i / 30, H2 * v0 * top(i / 30))); for (let i = 30; i >= 0; i--) pts.push(at(i / 30, H2 * v1 * top(i / 30))); poly(pts, col); };
