    x.fillStyle = C.weed; for (let k = 0; k < 40; k++) { const tx = fx + 2 + k * fw / 38 + ((k * 3) % 4); x.beginPath(); x.moveTo(tx - 2, sy - 1); x.lineTo(tx, sy - 7 - (k % 3)); x.lineTo(tx + 2, sy - 1); x.fill(); }
