    ctx.fillStyle = '#f4d0be'; ctx.beginPath(); ctx.ellipse(x0 - rx * 0.4 * u, y0 - ry * 0.55 * u, rx * 0.18 * u, ry * 0.14 * u, rot - 0.2, 0, Math.PI * 2); ctx.fill();
