  ctx.fillStyle = '#d4e8f4'; ctx.beginPath(); ctx.moveTo(bx + 18 * u, by + 1 * u); ctx.lineTo(bx + 38 * u, by + 0.2 * u); ctx.lineTo(bx + 38 * u, by + 1.4 * u); ctx.lineTo(bx + 18 * u, by + 2.4 * u); ctx.fill();
