  ctx.fillStyle = '#f8f8f4'; ctx.beginPath(); ctx.moveTo(bx - 23 * u, by - 7.4 * u); ctx.quadraticCurveTo(bx - 5 * u, by - 5.6 * u, bx + 20 * u, by - 6.6 * u); ctx.lineTo(bx + 19 * u, by - 1.2 * u); ctx.lineTo(bx - 21 * u, by - 1.2 * u); ctx.fill();
