  '..........###...',
  '.........##o#...',
  '.........#####dd',
  '..........###...',
  '#.........###...',
  '##.......####...',
  '#d#.....######..',
  '.###..#########.',
  '..###dddddd###..',
  '...##########...',
  '....dddddd##....',
  '.....######.....',
  '.......#..#.....',
  '......##.##.....',
