  '.......#.......',
  '......###......',
  '.....##o##.....',
  '......###......',
  '...#...#...#...',
  '..###..#..###..',
  '...###.#.###...',
  '.....#ddd#.....',
  '.#.....#.....#.',
  '###....#....###',
  '.###..d#d..###.',
