  ctx.fillStyle = '#f2f2ee'; ctx.fillRect(W * 0.62, H * 0.33, 6 * u, 1.4 * u); ctx.fillStyle = '#c8402e'; ctx.fillRect(W * 0.62 + 1.5 * u, H * 0.33 - 1.6 * u, 2.6 * u, 1.6 * u);
